def is_palindrome(s):
    s = s.lower().replace(' ', '')
    return s == s[::-1]

test_words = ["racecar", "hello", "A man a plan a canal Panama"]
for word in test_words:
    if is_palindrome(word):
        print(f"'{word}' is a palindrome")
    else:
        print(f"'{word}' is not a palindrome")

